
// rk_gal_css: galerijos modulio savarankiskas CSS (sekcija, slankiklis, tinklelis, lightbox)
add_action('wp_head', function () {
    if (is_admin()) return;
    $css = <<<'RKGALCSS'
.rkg{background:#fff;padding:64px 0;font-family:Inter,sans-serif;color:#64748B;font-size:17px;line-height:1.7}.rkg *{box-sizing:border-box}.rkg .wrap{max-width:1180px;margin:0 auto;padding:0 22px}.rkg .sec-head{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:16px;margin:0 0 28px}.rkg .sec-head h2{grid-column:2;margin:0;font-family:Manrope,sans-serif;font-size:38px;line-height:1.2;font-weight:800;letter-spacing:.01em;color:#166534;text-transform:uppercase;text-align:center}.rkg .sec-head .rkg-nav{grid-column:3;justify-self:end;display:flex;gap:8px}.rkg .sec-head button.rkg-arrow{width:40px;height:40px;padding:0;border-radius:50%;border:1px solid #E2E8F0;background:#fff;color:#166534;font-size:22px;line-height:1;font-weight:400;display:grid;place-items:center;box-shadow:none;cursor:pointer;transition:.2s;font-family:inherit}.rkg .sec-head button.rkg-arrow:hover{background:#166534;color:#fff;border-color:#166534}.rkg .sec-head button.rkg-arrow:disabled{opacity:.35;cursor:default;background:#fff;color:#166534;border-color:#E2E8F0}.rkg-grid{display:flex;gap:14px;overflow-x:auto;scroll-snap-type:x mandatory;scroll-behavior:smooth;padding:4px 2px 14px;scrollbar-width:none;align-items:stretch}.rkg-grid::-webkit-scrollbar{display:none}.rkg-grid.rkg-few{justify-content:center}.rkg-it{flex:0 0 calc((100% - 42px)/4);scroll-snap-align:start;display:flex;flex-direction:column;border-radius:14px;overflow:hidden;border:1px solid #E2E8F0;background:#fff;transition:.2s;height:auto}.rkg-it img{width:100%;aspect-ratio:4/3;height:auto;object-fit:cover;display:block;transition:transform .3s}.rkg-it:hover{box-shadow:0 22px 44px -24px rgba(15,74,40,.35);transform:translateY(-3px)}.rkg-it:hover img{transform:scale(1.04)}a.rkg-it,a.rkg-it:hover{text-decoration:none;color:#111827}.rkg-it .rkg-cap{display:block;flex:1;padding:10px 12px 11px;font-size:12.5px;font-weight:600;color:#111827;line-height:1.35;background:#fff;border-top:1px solid #E2E8F0}.rkg-dots{text-align:center;color:#64748B;font-size:12px;margin-top:2px}.rkg-nav-off,.rkg-dots.rkg-nav-off{display:none!important}.rkg-all .rkga-tabs{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin:0 0 22px}.rkg-all .rkga-tab{border:1px solid #E2E8F0;background:#fff;color:#166534;border-radius:999px;padding:9px 16px;font:600 13.5px/1.2 Inter,sans-serif;cursor:pointer;transition:.2s;box-shadow:none;text-transform:none;letter-spacing:normal}.rkg-all .rkga-tab:hover{border-color:#166534}.rkg-all .rkga-tab.on{background:#166534;color:#fff;border-color:#166534}.rkg-all .rkga-tab b{font-weight:600;opacity:.7;margin-left:2px}.rkga-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.rkga-grid .rkg-it{scroll-snap-align:none}.rkga-grid .rkg-it.rkga-off{display:none!important}.rkg-all .rkga-more{display:block;margin:26px auto 0;border:1px solid #166534;background:#fff;color:#166534;border-radius:999px;padding:12px 26px;font:600 14px/1.2 Inter,sans-serif;cursor:pointer;box-shadow:none;text-transform:none;letter-spacing:normal}.rkg-all .rkga-more:hover{background:#166534;color:#fff}@media(max-width:1024px){.rkg-it{flex-basis:calc((100% - 14px)/2)}.rkga-grid{grid-template-columns:1fr 1fr}}@media(max-width:767px){.rkg{padding:44px 0}.rkg .sec-head h2{font-size:28px}.rkg-it{flex-basis:85%}.rkga-grid{grid-template-columns:1fr}.rkg-grid.rkg-few{justify-content:flex-start}}.rk-lb{position:fixed;inset:0;background:rgba(17,24,39,.94);display:none;place-items:center;z-index:99999}.rk-lb.on{display:grid}.rk-lb figure{margin:0;max-width:94vw;text-align:center}.rk-lb img{max-width:94vw;max-height:80vh;border-radius:14px;box-shadow:0 30px 80px rgba(0,0,0,.5)}.rk-lb figcaption{color:#fff;margin-top:14px;font-weight:600;font-size:15px;font-family:Inter,sans-serif}.rk-lb button{position:absolute;background:rgba(255,255,255,.12);color:#fff;border:0;width:48px;height:48px;border-radius:50%;font-size:28px;cursor:pointer;display:grid;place-items:center}.rk-lb button:hover{background:rgba(255,255,255,.28)}.rk-lb .x,.rk-lb .x:hover{background:transparent;color:#fff}.rk-lb .x{top:20px;right:20px;font-size:20px}.rk-lb .p{left:16px;top:50%;transform:translateY(-50%)}.rk-lb .n{right:16px;top:50%;transform:translateY(-50%)}@media(max-width:600px){.rk-lb .p,.rk-lb .n{top:auto;bottom:16px;transform:none}}
RKGALCSS;
    echo '<style id="rk-gal">' . $css . '</style>';
}, 97);
